use serde_json::{Value, from_str};

pub fn solve(input: Value) -> Value {
    let cents = input.as_array().unwrap().get(0).unwrap().as_i64().unwrap();
    let n = input.as_array().unwrap().get(1).unwrap().as_i64().unwrap();
    if cents < 0 || n < 1 {
        return serde_json::Value::Null;
    }

    let mut shares = Vec::new();
    let mut remaining_cents = cents;
    let mut share_size = remaining_cents / n;
    let remainder = remaining_cents % n;

    for _ in 0..n {
        shares.push(share_size);
        if remainder > 0 {
            share_size += 1;
            remainder -= 1;
        }
    }

    serde_json::to_value(shares).unwrap()
}
